const headers = $json.headers || {};
const body = $json.body || {};
const query = $json.query || {};
const sessionKey = headers['x-builder-key'] || headers['X-Builder-Key'] || body.sessionKey || query.sessionKey || null;
const origin = headers['x-foundry-origin'] || headers['X-Foundry-Origin'] || body.origin || query.origin || '';
if (!sessionKey) return [{ json: { authorized: false, error: 'NO_SESSION_KEY', message: 'Missing session key.', requiresAuth: true } }];
if (sessionKey.length !== 32 || !/^[a-f0-9]{32}$/.test(sessionKey)) return [{ json: { authorized: false, error: 'INVALID_SESSION_FORMAT', message: 'Invalid session key format.', requiresAuth: true } }];
return [{ json: { ...($json), sessionKey, requestOrigin: origin, _needsValidation: true } }];

const input = $('Session Validation Node').first().json;
const sessions = $input.all().map(i => i.json);
const sessionData = sessions && sessions.length > 0 ? sessions[0] : null;
if (!sessionData || !sessionData.key) return [{ json: { authorized: false, error: 'SESSION_NOT_FOUND', message: 'Session expired or invalid.', requiresAuth: true } }];
const now = new Date();
const expiresAt = new Date(sessionData.expires_at);
if (expiresAt < now) return [{ json: { authorized: false, error: 'SESSION_EXPIRED', message: 'Your session has expired.', requiresAuth: true } }];
const isSuperuser = sessionData.superuser === true;
const tier = sessionData.tier ? String(sessionData.tier).trim() : '';
return [{ json: { authorized: true, sessionEmail: sessionData.email, sessionTier: tier, sessionIsSuperuser: isSuperuser, sessionKey: sessionData.key, ...input } }];

const error = $json.error || 'UNAUTHORIZED';
const message = $json.message || 'You are not authorized to access this feature.';
const requiresAuth = $json.requiresAuth === true;
const rateLimitExceeded = $json.rateLimitExceeded === true;
return [{ json: { ok: false, error, message, requiresAuth, rateLimitExceeded, ...(rateLimitExceeded ? { currentUsage: $json.currentUsage, limit: $json.limit, tier: $json.tier, resetDate: $json.resetDate, upgradeUrl: $json.upgradeUrl } : {}), authUrl: requiresAuth ? 'https://foundryrelay.dedicated2.com/webhook/oauth/patreon/login' : undefined } }];

const PATREON_CAMPAIGN_ID='9988159';
const PATREON_CREATOR_TOKEN='4YdoFngay8oKRuXgwN8Wso2YmLdGuAfoxgfGMi6nvEc';
const email=($json.sessionEmail||'').toLowerCase().trim();
const sessionKey=($json.sessionKey||'').trim();
const sessionTier=($json.sessionTier||'').toLowerCase().trim();
const isSuperuser=$json.sessionIsSuperuser===true;
const lookupKey=email||sessionKey;
if(!lookupKey)throw new Error('No email or session key found.');
const TIER_LIMITS={'free':3,'no tier':3,'none':3,'':3,'supporter':25,'professional':100,'premium':200,'superuser':999999};
if(isSuperuser){const currentMonth=new Date().toISOString().substring(0,7);const compositeKey=lookupKey+'::'+currentMonth;return [{json:{...($json),sessionTier:'superuser',_rateLimitCheck:{sessionKey:compositeKey,email:lookupKey,currentMonth,monthlyLimit:TIER_LIMITS['superuser'],tier:'superuser'}}}];}
let tier=sessionTier;
try{
  const url='https://www.patreon.com/api/oauth2/v2/campaigns/'+PATREON_CAMPAIGN_ID+'/members?include=currently_entitled_tiers&fields[member]=patron_status,currently_entitled_amount_cents,email&fields[tier]=title,amount_cents&page[count]=500';
  const resp=await $helpers.httpRequest({method:'GET',url,headers:{Authorization:'Bearer '+PATREON_CREATOR_TOKEN}});
  const tierMap={};
  for(const inc of(resp.included||[]))if(inc.type==='tier')tierMap[inc.id]=inc.attributes.title;
  const member=(resp.data||[]).find(m=>(m.attributes.email||'').toLowerCase()===email);
  if(member){
    const tierIds=member.relationships?.currently_entitled_tiers?.data||[];
    const tierNames=tierIds.map(t=>tierMap[t.id]).filter(Boolean);
    const paidTier=tierNames.filter(t=>t.toLowerCase()!=='free').sort((a,b)=>(TIER_LIMITS[b.toLowerCase()]||0)-(TIER_LIMITS[a.toLowerCase()]||0))[0];
    const liveTier=(paidTier||'').toLowerCase();
    if(member.attributes.patron_status==='active_patron'&&liveTier)tier=liveTier;
    else{const sessionIsPaid=TIER_LIMITS.hasOwnProperty(sessionTier)&&TIER_LIMITS[sessionTier]>3;tier=sessionIsPaid?sessionTier:'free';}
  }else{const sessionIsPaid=TIER_LIMITS.hasOwnProperty(sessionTier)&&TIER_LIMITS[sessionTier]>3;tier=sessionIsPaid?sessionTier:(sessionTier||'free');}
}catch(e){tier=sessionTier||'free';}
let monthlyLimit=TIER_LIMITS.hasOwnProperty(tier)?TIER_LIMITS[tier]:25;
if(!tier||tier==='free'||tier==='')monthlyLimit=3;
const currentMonth=new Date().toISOString().substring(0,7);
const compositeKey=lookupKey+'::'+currentMonth;
return [{json:{...($json),sessionTier:tier,_rateLimitCheck:{sessionKey:compositeKey,email:lookupKey,currentMonth,monthlyLimit,tier}}}];

const STORE_COST=1;
const rateLimitData=$('Rate Limit: Prepare Check').first().json._rateLimitCheck;
const monthlyLimit=rateLimitData.monthlyLimit;
const tier=rateLimitData.tier;
const usageRecords=$input.all().map(i=>i.json);
const usageData=usageRecords&&usageRecords.length>0?usageRecords[0]:null;
const currentCount=usageData?.npc_count||0;
if(currentCount+STORE_COST>monthlyLimit){
  const resetDate=new Date();resetDate.setMonth(resetDate.getMonth()+1);resetDate.setDate(1);resetDate.setHours(0,0,0,0);
  return [{json:{ok:false,rateLimitExceeded:true,error:'RATE_LIMIT_EXCEEDED',message:'You have used '+currentCount+' of your '+monthlyLimit+' monthly uses for the "'+(tier||'free')+'" tier. Resets on '+resetDate.toLocaleDateString()+'.',currentUsage:currentCount,limit:monthlyLimit,tier,resetDate:resetDate.toISOString(),upgradeUrl:'https://www.patreon.com/c/CelestiaTools/membership'}}];
}
const originalData=$('Rate Limit: Prepare Check').first().json;
return [{json:{...originalData,_rateLimitCheck:{...rateLimitData,currentCount,usageRecordExists:!!usageData,usageRecordId:usageData?.id||null}}}];

const STORE_COST=1;
const rateLimitValidateData=$('Rate Limit: Validate').first().json;
const rateLimitData=rateLimitValidateData._rateLimitCheck;
const compositeKey=rateLimitData.sessionKey;
const currentMonth=rateLimitData.currentMonth;
const currentCount=rateLimitData.currentCount||0;
const now=new Date().toISOString();
return [{json:{...rateLimitValidateData,session_key:compositeKey,month:currentMonth,npc_count:currentCount+STORE_COST,last_created:now,_usageUpdate:{session_key:compositeKey,month:currentMonth,npc_count:currentCount+STORE_COST,last_created:now}}}];

const originalData = $('Increment Usage Counter').first()?.json;
if (!originalData || !originalData.body) throw new Error('Could not restore request context: Increment Usage Counter data missing');
return [{ json: originalData }];

let input = $json;
if (Array.isArray(input)) input = input[0];
if (input?.body) input = input.body;
const name = String(input.name || '').trim();
if (!name) throw new Error('Missing required field: name');
if (name.length > 120) throw new Error('Item name too long');
return [{ json: { name, _prepSuccess: true } }];

// Query the Archives of Nethys search index for the named item.
const name = $('Prep Wiki Input').first().json.name;
const body = JSON.stringify({
  size: 5,
  query: { bool: {
    must: [{ multi_match: { query: name, fields: ['name^5', 'text'], fuzziness: 'AUTO' } }],
    filter: [{ terms: { category: ['equipment', 'weapon', 'armor', 'shield'] } }],
  } },
});
let hits = [];
try {
  const resp = await $helpers.httpRequest({
    method: 'POST',
    url: 'https://elasticsearch.aonprd.com/aon/_search',
    headers: { 'Content-Type': 'application/json' },
    body,
    json: false,
  });
  const parsed = typeof resp === 'string' ? JSON.parse(resp) : resp;
  hits = parsed?.hits?.hits || [];
} catch (e) {
  return [{ json: { _wikiError: 'Archives of Nethys is unreachable right now (' + e.message + ').' } }];
}
if (!hits.length) return [{ json: { _wikiError: 'No Archives of Nethys entry found for "' + name + '".' } }];
const best = hits[0]._source || {};
const source = {
  name:      best.name || name,
  category:  best.category || '',
  itemCategory: best.item_category || '',
  level:     best.level ?? null,
  price:     best.price_raw || best.price || '',
  rarity:    best.rarity || 'common',
  traits:    best.trait_raw || best.trait || [],
  bulk:      best.bulk_raw || best.bulk || '',
  usage:     best.usage || '',
  text:      String(best.text || best.markdown || '').slice(0, 6000),
  url:       best.url ? 'https://2e.aonprd.com' + best.url : '',
};
return [{ json: { name, wikiSource: source } }];

const { name, wikiSource } = $json;
const SYSTEM_PROMPT = 'You are a PF2e Foundry VTT item converter. You are given raw item data from the Archives of Nethys. ' +
  'Convert it FAITHFULLY into a Foundry VTT pf2e (Remaster) item. Return STRICT JSON only (no markdown, no code fences).\n\n' +
  'TOP-LEVEL SHAPE: { "name", "type", "img": "icons/svg/item-bag.svg", "system": {...} }\n' +
  'Valid types: weapon, armor, shield, equipment, consumable, treasure, backpack, book.\n' +
  'system fields: description { "value": "<p>…</p>" } (convert the source text to clean HTML, keep the mechanics EXACT), ' +
  'level { "value" }, traits { "value": [slugs], "rarity" }, price { "value": { "gp": N, "sp": N, "cp": N } } parsed from the source price, ' +
  'bulk { "value" } (L = 0.1), quantity 1, size "med", publication { "title": "Archives of Nethys", "license": "ORC", "remaster": true }.\n' +
  'Type-specific fields (damage/runes/category/group/acBonus/uses) must match the source exactly where stated. ' +
  'Do not invent mechanics that are not in the source. Do not change or water down any numbers.';
const USER_PROMPT = 'Requested item: ' + name + '\n\nARCHIVES OF NETHYS DATA:\n' + JSON.stringify(wikiSource, null, 1) + '\n\nReturn ONLY the Foundry item JSON.';
return [{ json: { ...$json, system: SYSTEM_PROMPT, user: USER_PROMPT } }];

function safeParse(raw) {
  if (!raw) return null;
  if (typeof raw === 'object') return raw;
  try { let s = String(raw).trim(); if (s.startsWith('```')) s = s.replace(/^```(?:json)?\s*/, '').replace(/```\s*$/, ''); return JSON.parse(s); } catch { return null; }
}
const prep = $('Prep Wiki Input').first().json;
const wiki = $('Fetch Wiki Data').first().json.wikiSource || {};
const raw = $json.message?.content ?? $json.completion ?? $json.text ?? null;
const parsed = safeParse(raw);
if (!parsed || typeof parsed !== 'object') {
  return [{ json: { ok: false, error: 'CONVERT_FAILED', message: 'The converter returned unusable output — try again.' } }];
}
const VALID_TYPES = new Set(['weapon','armor','shield','equipment','consumable','treasure','backpack','book']);
const item = { name: String(parsed.name || prep.name).slice(0, 120), type: VALID_TYPES.has(parsed.type) ? parsed.type : 'equipment', img: String(parsed.img || 'icons/svg/item-bag.svg'), system: parsed.system && typeof parsed.system === 'object' ? parsed.system : {} };
const s = item.system;
if (!s.description || typeof s.description.value !== 'string') s.description = { value: String(s.description?.value || s.description || '') };
s.level = { value: Number(s.level?.value ?? s.level ?? wiki.level ?? 0) || 0 };
if (!s.traits || !Array.isArray(s.traits.value)) s.traits = { value: [], rarity: 'common', otherTags: [] };
s.publication = { title: 'Archives of Nethys', license: 'ORC', remaster: true };
s.quantity = 1;
return [{ json: { ok: true, foundryItem: item, item, source: { name: wiki.name, url: wiki.url || '' }, message: 'Converted "' + item.name + '" from Archives of Nethys.' } }];
